"""A legitimately off-screen tower still casts a visible on-screen shadow."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib,base64
source=(ROOT/'assets/game.js').read_text();out=ROOT/'docs/previews/city-continuity';out.mkdir(parents=True,exist_ok=True)
probe=r'''window.__shadowCull=()=>{__townTest.capture({zoom:1,night:false});const before=JSON.stringify(G),sx=cam.x-cw/2,sy=cam.y-ch/2,a={kind:'building',id:17,b:{id:17,kind:'tower',condition:100,firm:-1,hh:-1},x:sx-140,y:cam.y,w:2,d:2},make=()=>{const c=document.createElement('canvas');c.width=cv.width;c.height=cv.height;const g=c.getContext('2d');g.fillStyle='#90a276';g.fillRect(0,0,c.width,c.height);mapPaintTransform(g);return{c,g};},reference=make(),old=make(),fixed=make();paintCastShadows(reference.g,[a]);const oldVisible=a.x>=sx-132&&a.x<=sx+cw+132&&a.y>=sy-84&&a.y<=sy+ch+172,newVisible=sceneIntersectsView(a,sx,sy,cw,ch);if(oldVisible)paintCastShadows(old.g,[a]);if(newVisible)paintCastShadows(fixed.g,[a]);const expected=reference.g.getImageData(0,0,cv.width,cv.height).data,compare=g=>{const pixels=g.getImageData(0,0,cv.width,cv.height).data;let n=0,max=0;for(let i=0;i<pixels.length;i++){const d=Math.abs(pixels[i]-expected[i]);if(d>2)n++;max=Math.max(max,d);}return{channels:n,max};};window.__shadowCullImages={old:old.c.toDataURL(),fixed:fixed.c.toDataURL(),reference:reference.c.toDataURL()};return{oldVisible,newVisible,old:compare(old.g),fixed:compare(fixed.g),unchanged:before===JSON.stringify(G)};};'''
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':640,'height':360});p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();p.keyboard.press('Escape');r=p.evaluate('__shadowCull()');assert not r['oldVisible'] and r['newVisible'] and r['old']['channels']>50 and r['fixed']['channels']==0 and r['unchanged'],r
 for n,data in p.evaluate('__shadowCullImages').items():(out/('shadow-'+n+'.png')).write_bytes(base64.b64decode(data.split(',')[1]))
 b.close()
r.update(source_sha256=hashlib.sha256(source.encode()).hexdigest(),fixture='Render-only valid two-plot tower geometry; no town property or economic fields changed.');(out/'shadow-checks.json').write_text(json.dumps(r,indent=2)+'\n');print(r)
